package com.yankardev.sitrac.mantenimiento.infrastructure.adapter.out.persistence;
import com.yankardev.sitrac.mantenimiento.domain.model.*;import jakarta.persistence.*;import lombok.*;import java.math.BigDecimal;import java.time.LocalDate;
@Entity @Table(name="mantenimientos") @Getter @Setter @Builder @NoArgsConstructor @AllArgsConstructor
public class MantenimientoJpaEntity{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;@Enumerated(EnumType.STRING) @Column(name="tipo_unidad",nullable=false,length=20) private TipoUnidad tipoUnidad;@Column(name="unidad_id",nullable=false) private Long unidadId;@Enumerated(EnumType.STRING) @Column(name="tipo_mantenimiento",nullable=false,length=20) private TipoMantenimiento tipoMantenimiento;@Column(name="fecha_inicio",nullable=false) private LocalDate fechaInicio;@Column(name="fecha_fin") private LocalDate fechaFin;@Column(nullable=false,length=500) private String descripcion;@Column(precision=12,scale=2) private BigDecimal costo;@Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private EstadoMantenimiento estado;}